import { errors } from "@appport/protocol";
import { readExport } from "../legacy/crm.mjs";

// Who to send a customer's invoices to.
//
// NOTE FOR THE CALLING AGENT: this does NOT yet read from the application's
// customer store. The store's module path and API were not among the files
// provided, so wiring it in would have meant guessing an import that could
// break runtime.load.
//
// What this version does instead:
// - It stops going through customers.lookup.mjs (the lookup handler).
// - It reads the same CRM export that the lookup handler read.
// - Answers on existing state are therefore identical: the same customerId,
//   name and email, and NOT_FOUND for unknown ids.
//
// It still depends on src/legacy/crm.mjs. To finish the goal, replace
// readExport() below with the customer store's read and map its fields to
// customerId/name/email.
//
// The published contract still declares
// `requires: customers.lookup@1 (observes)`. This handler no longer calls that
// handler at runtime. Whether that declaration should change is the contract
// owner's call; this file leaves the contract alone.
export async function billingContact(input) {
  const row = readExport().find((r) => r.cust_id === input.customerId);
  if (!row) {
    throw errors.notFound(`no customer ${input.customerId}`);
  }
  return { customerId: row.cust_id, name: row.full_name, email: row.mail };
}
=== END FILE ===

